lines = context.strip().split('\n')
entailment_count = 0

for line in lines:
    if " -> " in line:
        # Extract the label after the " -> " marker
        label = line.split(" -> ")[1].strip()
        if label == "entailment":
            entailment_count += 1

print(entailment_count)

# Extract only the classification (true/false) from each result
classifications = []
for result in results:
    if "True" in result or "true" in result:
        classifications.append("true")
    elif "False" in result or "false" in result:
        classifications.append("false")
    else:
        # Fallback: if neither true nor false is found, default to false
        classifications.append("false")

print(f"Classifications: {classifications}")
print(f"Number of false claims: {classifications.count('false')}")

