    if " -> " in line:
        # Split by " -> " and get the part after the marker
        parts = line.split(" -> ", 1)
        if len(parts) == 2:
            label = parts[1].strip()
            if label == "contradiction":
                contradiction_count += 1
            elif label == "neutral":
                neutral_count += 1

print(f"Contradiction count: {contradiction_count}")
print(f"Neutral count: {neutral_count}")

