import re

contradiction_count = 0
neutral_count = 0

# Regex to match the label in the response
label_pattern = re.compile(r"Relationship:\s*([a-zA-Z]+)", re.IGNORECASE)

for response in all_responses:
    match = label_pattern.search(response)
    if match:
        label = match.group(1).strip().lower()
        if label == "contradiction":
            contradiction_count += 1
        elif label == "neutral":
            neutral_count += 1
    else:
        # Fallback: check if label is in the text
        if "contradiction" in response.lower():
            contradiction_count += 1
        elif "neutral" in response.lower():
            neutral_count += 1

print(f"Contradiction count: {contradiction_count}")
print(f"Neutral count: {neutral_count}")

